package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class NativeUiReadyHelperWiringTest {
 String source()throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/NativeUiStructureHelper.java"));}
 @Test public void onlyExactOptionalMode(){assertTrue(NativeUiStructureHelper.validReadyArguments(new String[2]));assertTrue(NativeUiStructureHelper.validReadyArguments(new String[]{"n","d","READY_V49"}));assertFalse(NativeUiStructureHelper.validReadyArguments(new String[]{"n","d","READY_V49 "}));assertFalse(NativeUiStructureHelper.validReadyArguments(new String[4]));}
 @Test public void singleIdleCallAfterConfigBeforeSingleRoot()throws Exception{String s=source();int config=s.indexOf("readback.flags != requiredFlags");int idle=s.indexOf("automation.waitForIdle(500,3000)");int root=s.indexOf("automation.getRootInActiveWindow()");assertTrue(config<idle&&idle<root);assertEquals(idle,s.lastIndexOf("automation.waitForIdle(500,3000)"));assertEquals(root,s.lastIndexOf("automation.getRootInActiveWindow()"));assertTrue(s.substring(config,idle).contains("if(readyMode)"));}
 @Test public void idleFailureThrowsBeforeRootNoRetry()throws Exception{String s=source();assertTrue(s.contains("catch(java.util.concurrent.TimeoutException timedOut){idle=NativeUiReadyDiagnostics.Idle.TIMEOUT;throw new Stop(NativeUiStructureProtocol.Reason.IDLE_TIMEOUT);}"));assertTrue(s.contains("throw new Stop(NativeUiStructureProtocol.Reason.IDLE_FAILED)"));assertTrue(s.contains("readEnd-SystemClock.elapsedRealtime()<3000"));}
 @Test public void legacyDeadlineAndEarliestTimePreserved()throws Exception{String s=source();assertTrue(s.contains("start + (readyMode?8000:5000)"));assertTrue(s.contains("new NativeUiStructureProtocol.Report(args[0], start,"));assertTrue(s.contains("readyMode?diagnostics.result(idle):null"));}
 @Test public void blockerValidTreeDoesNotRunCounterParser()throws Exception{String s=source();int guard=s.indexOf("if(!readyMode||!diagnostics.blocked())");int parse=s.indexOf("NativeUiStructureParser.parse(records)");assertTrue(guard>=0&&guard<parse);assertTrue(s.contains("search = NativeUiStructureProtocol.Task.unknown()"));assertTrue(s.contains("reading = NativeUiStructureProtocol.Task.unknown()"));}
}
